#ifndef GGML_BACKEND_QUANT_H
#define GGML_BACKEND_QUANT_H

#include "ggml.h"
#include "ggml-backend.h"

#ifdef __cplusplus
extern "C" {
#endif

// Per-backend quant operations. NULL fields = not supported natively.
// If all fields are NULL, the type has no GPU kernel and falls back to CPU.
struct ggml_backend_quant_ops {
    // Flash attention vector kernel (NULL = use CPU dequant fallback)
    int (*fattn_vec)(struct ggml_context * ctx, struct ggml_tensor * q,
                     struct ggml_tensor * k, struct ggml_tensor * v,
                     struct ggml_tensor * dst, int32_t n_head, int32_t n_kv, float scale,
                     float max_alibi_bias, int32_t n_logit_src);
    // Row dequantization on device (NULL = use type_traits->to_float on CPU)
    void (*dequantize_row)(const void * x, float * y, int64_t k);
    // Row quantization on device (NULL = use type_traits->from_float_ref on CPU)
    void (*quantize_row)(const float * x, void * y, int64_t nrows, int64_t n_per_row);
};

// Registration: called by each backend during init for each quant type it supports
GGML_API void ggml_backend_register_quant_ops(
    ggml_backend_dev_t           dev,
    enum ggml_type               type,
    const struct ggml_backend_quant_ops * ops);

// Query: does this backend have native support for this quant type?
GGML_API bool ggml_backend_supports_quant(
    ggml_backend_dev_t dev,
    enum ggml_type     type);

// Get ops for a type on a device (NULL = not supported, use CPU fallback)
GGML_API const struct ggml_backend_quant_ops * ggml_backend_get_quant_ops(
    ggml_backend_dev_t dev,
    enum ggml_type     type);

#ifdef __cplusplus
}
#endif
#endif

#include "ggml-backend-quant.h"
#include <string.h>

#define MAX_BACKENDS 16
#define MAX_QUANT_OPS 64

struct backend_quant_entry {
    ggml_backend_dev_t dev;
    enum ggml_type type;
    struct ggml_backend_quant_ops ops;
};

static struct backend_quant_entry registry[MAX_BACKENDS * MAX_QUANT_OPS];
static int registry_count = 0;

void ggml_backend_register_quant_ops(
    ggml_backend_dev_t dev,
    enum ggml_type type,
    const struct ggml_backend_quant_ops * ops) {
    if (registry_count >= MAX_BACKENDS * MAX_QUANT_OPS) return;
    // Check for duplicate (same dev + type)
    for (int i = 0; i < registry_count; i++) {
        if (registry[i].dev == dev && registry[i].type == type) {
            registry[i].ops = *ops;
            return;
        }
    }
    registry[registry_count].dev = dev;
    registry[registry_count].type = type;
    registry[registry_count].ops = ops ? *ops : (struct ggml_backend_quant_ops){0};
    registry_count++;
}

bool ggml_backend_supports_quant(ggml_backend_dev_t dev, enum ggml_type type) {
    for (int i = 0; i < registry_count; i++) {
        if (registry[i].dev == dev && registry[i].type == type) {
            return true;
        }
    }
    return false;
}

const struct ggml_backend_quant_ops * ggml_backend_get_quant_ops(
    ggml_backend_dev_t dev, enum ggml_type type) {
    for (int i = 0; i < registry_count; i++) {
        if (registry[i].dev == dev && registry[i].type == type) {
            return &registry[i].ops;
        }
    }
    return NULL;
}

