#pragma once
#include <vector>
#include <cstdint>

// Compute KL divergence D_KL(P || Q) between two logit distributions.
// P = reference (typically F16 model), Q = quantized model.
// Returns divergence in nats. Lower = better quantization quality.
double kl_divergence(
    const float * logits_ref,   // reference model logits [n_vocab]
    const float * logits_quant, // quantized model logits [n_vocab]
    int n_vocab);

// Batch KL divergence: compute average KL across a sequence of token positions.
struct kl_result {
    double mean_kl;
    double max_kl;
    double p95_kl;
    int    n_tokens;
};

struct kl_result kl_divergence_batch(
    const float * logits_ref,   // [n_tokens, n_vocab]
    const float * logits_quant, // [n_tokens, n_vocab]
    int n_tokens,
    int n_vocab);

#include "kl_divergence.h"
#include <cmath>
#include <algorithm>

static void softmax(float * probs, const float * logits, int n) {
    float max_val = *std::max_element(logits, logits + n);
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        probs[i] = expf(logits[i] - max_val);
        sum += probs[i];
    }
    float inv_sum = 1.0f / sum;
    for (int i = 0; i < n; i++) probs[i] *= inv_sum;
}

double kl_divergence(const float * ref, const float * quant, int n) {
    std::vector<float> p(n), q(n);
    softmax(p.data(), ref, n);
    softmax(q.data(), quant, n);
    double kl = 0.0;
    for (int i = 0; i < n; i++) {
        if (p[i] > 1e-12f && q[i] > 1e-12f) {
            kl += p[i] * log(p[i] / q[i]);
        }
    }
    return kl;
}

#pragma once
#include "ggml.h"

struct round_trip_result {
