// Implements ggml_backend_i for hybrid CPU+iGPU execution.
// Key methods:
// - hybrid_buffer_alloc: allocates UMA shared memory (VK_EXT_external_memory_host on Linux, ReBAR on Windows)
// - hybrid_graph_compute: dispatches each op to CPU threads or iGPU shaders based on adaptive split
// - hybrid_supports_op: all ops supported (CPU fallback for anything iGPU can't do)
//
// The backend registers quant support via ggml_backend_register_quant_ops()
// for types that have Vulkan dequant shaders (Phase 15).

#include "ggml-hybrid.h"
#include "ggml-backend-impl.h"
#include "ggml-quant-caps.h"
#include "ggml-backend-quant.h"

// Static state
static struct {
    bool initialized;
    bool uma_capable;
    struct ggml_hybrid_thermal_state thermal;
    // Vulkan handles for iGPU dispatch
    // VkDevice, VkQueue, VkCommandBuffer, etc.
} hybrid_state;

// ... ggml_backend_i implementation ...
// Key: hybrid_graph_compute_dispatch() splits each GEMM by rows
// CPU rows: [0 .. split_row)
// iGPU rows: [split_row .. total_rows)
// No synchronization between them — disjoint output memory

// UMA buffer: single physical allocation, dual access
//
// VkMemoryAllocateFlags with VK_MEMORY_ALLOCATE_DEVICE_ADDRESS_BIT
// + VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT
// + VK_MEMORY_PROPERTY_HOST_COHERENT_BIT | VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT
//
// Result: void* ptr usable by CPU AND VkBuffer usable by iGPU,
// pointing to the same physical pages. Zero copies, zero sync.

// Disjoint UMA Tensor Slicing:
//
// For mul_mat (GEMM): dst = src0 @ src1
//   src0: weights (read-only, shared by both units)
//   src1: activations (read-only, shared by both units)
//   dst: output (split: CPU writes top rows, iGPU writes bottom rows)
//
// cpu_view = dst[0 : split_row]
// igpu_view = dst[split_row : total_rows]
//
// Launch both concurrently:
//   cpu_threadpool->submit(gemm_simd, cpu_view, src0, src1)
//   vulkan_queue->submit(gemm_shader, igpu_view, src0, src1)
//
// NO BARRIER between them. The ggml graph scheduler handles
// inter-op dependencies at the graph level, not within a single op.

void hybrid_mul_mat_dispatch(ggml_tensor * dst, const ggml_tensor * src0, const ggml_tensor * src1) {
    const float cpu_ratio = hybrid_state.thermal.cpu_to_igpu_ratio;
    const int total_rows = (int)dst->ne[1];
    const int split_row = (int)(total_rows * cpu_ratio);

    if (split_row > 0) {
        // CPU slice: AVX2/AVX-512/NEON optimized GEMM
        cpu_pool.submit([&]() {
            ggml_compute_mul_mat_cpu(dst, src0, src1, /*row_start=*/0, /*row_end=*/split_row);
        });
    }

    if (split_row < total_rows) {
        // iGPU slice: Vulkan compute shader with inline dequant
        vk_queue.submit(gemm_shader, dst, src0, src1, /*row_start=*/split_row, /*row_end=*/total_rows);
    }

    // Wait for both — but NO data copy, both wrote to their own rows in dst
    cpu_pool.wait();
    vk_queue.wait();
}

// Adaptive Thermal Balancer
//
// After each transformer layer, measure:
//   cpu_time = time for CPU to complete its rows
//   igpu_time = time for iGPU to complete its rows
//
// If igpu_time > cpu_time * 1.1 (iGPU throttling or memory-bound):
//   increase cpu_ratio by 0.05 (shift work to CPU)
// If cpu_time > igpu_time * 1.1 (CPU is bottleneck):
//   decrease cpu_ratio by 0.05 (shift work to iGPU)
//
// Clamp cpu_ratio to [0.1, 0.9] — never go fully one-sided
// (both units should always be active to maximize throughput).
//
// Also reads thermal zones:
//   /sys/class/thermal/thermal_zone*/temp (Linux)
//   system_profiler SPMDataType (macOS)
// If either unit exceeds 85C, reduce its workload aggressively.

struct thermal_balancer {
    float cpu_ratio = 0.5f;  // start at 50/50
    float cpu_ema_time = 0.0f;  // exponential moving average
    float igpu_ema_time = 0.0f;

    void update(float cpu_time, float igpu_time) {
        cpu_ema_time = cpu_ema_time * 0.9f + cpu_time * 0.1f;
        igpu_ema_time = igpu_ema_time * 0.9f + igpu_time * 0.1f;

        if (igpu_ema_time > cpu_ema_time * 1.1f) {
            cpu_ratio = std::min(0.9f, cpu_ratio + 0.05f);
        } else if (cpu_ema_time > igpu_ema_time * 1.1f) {
            cpu_ratio = std::max(0.1f, cpu_ratio - 0.05f);
        }

        // Thermal override
        auto therm = read_thermal_zones();
        if (therm.igpu_temp > 85.0f) cpu_ratio = std::min(0.9f, cpu_ratio + 0.1f);
        if (therm.cpu_temp > 85.0f) cpu_ratio = std::max(0.1f, cpu_ratio - 0.1f);
    }
};

