#version 460
#extension GL_KHR_shader_subgroup_arithmetic : enable
#extension GL_KHR_shader_subgroup_shuffle : enable

layout(local_size_x = 32) in; // 1 subgroup = 32 threads

layout(set=0, binding=0) readonly buffer Weights { uint weights[]; };
layout(set=0, binding=1) readonly buffer Activations { float x[]; };
layout(set=0, binding=2) buffer Output { float y[]; };
layout(push_constant) uniform Push { int M; int N; int K; int row_offset; } pc;

void main() {
    uint lane = gl_SubgroupInvocationID;
    uint row = gl_WorkGroupID.x + pc.row_offset;
    uint col = gl_WorkGroupID.y;
    if (row >= pc.N || col >= pc.M) return;

    float sum = 0.0;
    // Q4_0 block: 32 elements per block, 1 fp16 scale + 16 packed nibbles
    for (uint k = 0; k < pc.K; k += 32) {
        uint block_idx = (row * pc.K + k) / 32;
        // Load scale (broadcast via subgroup shuffle)
        float d = subgroupShuffle(unpackHalf2x16(weights[block_idx * 18]).x, 0);
        // Load nibble for this lane
        uint q = weights[block_idx * 18 + 2 + lane / 2];
        float w = d * (((q >> (lane % 2 * 4)) & 0xF) - 8);
        // Dot product with activation
        sum += w * x[col * pc.K + k + lane];
    }
    // Warp-level reduction
    sum = subgroupAdd(sum);
    if (lane == 0) atomicAdd(y[col * pc.N + row], sum);
}

